using Michaelhouse.Mobile.Models;
using Michaelhouse.Mobile.Services;
using ZXing.Net.Maui;
using ZXing.Net.Maui.Controls;
namespace Michaelhouse.Mobile.Pages;

internal static class MobileBindings
{
    public static View TextLabel(string path)
    {
        var label = new Label { Style = (Style)Application.Current!.Resources["CardLabel"] };
        label.SetBinding(Label.TextProperty, path);
        var card = new Border { Content = label, Stroke = Color.FromArgb("#EEEEEE"), StrokeThickness = 1, Padding = 0 };
        return card;
    }
}

public sealed class LoginPage : ContentPage { readonly Entry email=new(){Placeholder="Email"}; readonly Entry password=new(){Placeholder="Password",IsPassword=true}; readonly Label msg=new(){TextColor=Colors.Firebrick}; readonly MobileApiClient api; readonly SessionService session; public LoginPage(MobileApiClient a,SessionService s){api=a;session=s;Content=new VerticalStackLayout{Padding=28,Children={new Label{Text="Michaelhouse",Style=(Style)Application.Current!.Resources["Headline"]},email,password,new Button{Text="Sign in",Command=new Command(async()=>await Go())},msg}};} async Task Go(){try{msg.Text="Signing in…";var x=await api.PostAsync<LoginResponse>("auth/login",new{email=email.Text,password=password.Text});if(String.IsNullOrEmpty(x?.Token))throw new InvalidOperationException("The server did not return a login token.");await session.SaveAsync(x.Token);api.SetToken(x.Token);Page page=String.Equals(x.Role,"Teacher",StringComparison.OrdinalIgnoreCase)?new TeacherSessionsPage(api,session,x.Name):String.Equals(x.Role,"Driver",StringComparison.OrdinalIgnoreCase)?new DriverTripsPage(api,session,x.Name):String.Equals(x.Role,"HouseMaster",StringComparison.OrdinalIgnoreCase)?new HouseMasterHomePage(api,session,x.Name):String.Equals(x.Role,"Student",StringComparison.OrdinalIgnoreCase)?new DashboardPage(api,session,x.Name):throw new InvalidOperationException("This mobile portal is not available to this account.");await Navigation.PushAsync(page);Navigation.RemovePage(this);}catch(Exception ex){msg.Text=String.IsNullOrWhiteSpace(ex.Message)?"Sign-in failed.":ex.Message;}} }
public sealed class DashboardPage : ContentPage { public DashboardPage(MobileApiClient a,SessionService s,string n){Title="Michaelhouse";Content=new VerticalStackLayout{Padding=20,Spacing=12,Children={new Label{Text="Welcome, "+n,Style=(Style)Application.Current!.Resources["Headline"],HorizontalTextAlignment=TextAlignment.Start},B("My profile",()=>Navigation.PushAsync(new StudentProfilePage(a))),B("Timetable",()=>Navigation.PushAsync(new StudentTimetablePage(a))),B("Results",()=>Navigation.PushAsync(new StudentResultsPage(a))),B("Attendance",()=>Navigation.PushAsync(new StudentAttendancePage(a))),B("Alerts",()=>Navigation.PushAsync(new StudentAlertsPage(a))),B("Emergency safety",()=>Navigation.PushAsync(new StudentEmergencyPage(a))),B("Sign out",async()=>{s.Clear();a.SetToken(null);await Navigation.PushAsync(new LoginPage(a,s));})}};} static Button B(string t,Func<Task> f)=>new(){Text=t,Command=new Command(async()=>await f())}; }

public sealed class StudentProfilePage : ContentPage { readonly MobileApiClient api; readonly Label detail=new(); public StudentProfilePage(MobileApiClient a){api=a;Title="My profile";Content=new VerticalStackLayout{Padding=20,Children={detail}};} protected override async void OnAppearing(){base.OnAppearing();try{var s=await api.GetAsync<StudentDto>("student/profile");detail.Text=s==null?"Profile unavailable.":$"{s.Name}\n{s.StudentNumber}\n{s.Grade}";}catch{detail.Text="Unable to load your profile.";}} }
