public sealed class HouseMasterResidencesPage : ContentPage { readonly MobileApiClient api; readonly CollectionView list=new(); readonly Label state=new(); public HouseMasterResidencesPage(MobileApiClient a){api=a;Title="Emergency roll call";list.ItemTemplate=new DataTemplate(()=>MobileBindings.TextLabel("Name"));list.SelectionChanged+=async(_,e)=>{if(e.CurrentSelection.FirstOrDefault()is HouseMasterResidenceDto x)await Navigation.PushAsync(new EmergencyRollCallPage(api,x));};Content=new VerticalStackLayout{Padding=20,Children={state,list}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<List<HouseMasterResidenceDto>>("housemaster/residences")??[];list.ItemsSource=x;state.Text=x.Count==0?"No residence is assigned to you.":"";}catch{state.Text="Unable to load your residences.";}} }
public sealed class EmergencyRollCallPage : ContentPage { readonly MobileApiClient api; readonly HouseMasterResidenceDto residence; readonly VerticalStackLayout rows=new(){Spacing=8}; readonly Label state=new(); public EmergencyRollCallPage(MobileApiClient a,HouseMasterResidenceDto r){api=a;residence=r;Title="Emergency roll call";Content=new ScrollView{Content=new VerticalStackLayout{Padding=20,Spacing=12,Children={new Label{Text=r.Name,Style=(Style)Application.Current!.Resources["SubHeadline"],HorizontalTextAlignment=TextAlignment.Start},state,rows}}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<List<RollCallStudentDto>>($"housemaster/residences/{residence.Id}/rollcall")??[];rows.Children.Clear();foreach(var student in x)rows.Children.Add(new Button{Text="Mark present · "+student.Name,Command=new Command(async()=>await Mark(student))});state.Text=x.Count==0?"No active students are listed.":"";}catch{state.Text="Unable to load the emergency roll call.";}} async Task Mark(RollCallStudentDto student){try{await api.PostAsync<object>($"housemaster/residences/{residence.Id}/rollcall/{student.StudentId}",null);state.Text=student.Name+" marked present.";}catch(Exception ex){state.Text=ex.Message;}} }
